import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"HVDC取代UPS：AIDC供电架构千亿替换——2026转折年受益链条","description":"","frontmatter":{"title":"HVDC取代UPS：AIDC供电架构千亿替换——2026转折年受益链条","updated":"2026-06-28T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/HVDC取代UPS_AIDC供电架构千亿替换深度分析报告.md","filePath":"智算中心投建运/HVDC取代UPS_AIDC供电架构千亿替换深度分析报告.md","lastUpdated":1789119850000}'),o={name:"智算中心投建运/HVDC取代UPS_AIDC供电架构千亿替换深度分析报告.md"};function i(l,t,s,n,h,c){return d(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="hvdc取代ups-aidc供电架构千亿替换——2026转折年-从变压器到配电柜的受益链条" tabindex="-1">HVDC取代UPS：AIDC供电架构千亿替换——2026转折年，从变压器到配电柜的受益链条 <a class="header-anchor" href="#hvdc取代ups-aidc供电架构千亿替换——2026转折年-从变压器到配电柜的受益链条" aria-label="Permalink to &quot;HVDC取代UPS：AIDC供电架构千亿替换——2026转折年，从变压器到配电柜的受益链条&quot;">​</a></h1><blockquote><p><strong>报告日期</strong>: 2026年6月21日 <strong>分析框架</strong>: 行业投资级结构化研究</p></blockquote><hr><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>2026年是HVDC（高压直流）数据中心供电产业化元年。受AI算力集群功耗指数级增长驱动，数据中心供电架构正从传统交流UPS向800V高压直流（HVDC）全面演进。SemiAnalysis预计2030年800VDC覆盖的数据中心增量容量达39GW，对应电源侧柜和固态变压器两大核心市场合计约$24B。中国市场2030年HVDC市场超800亿元（CAGR 122%），海外市场超1400亿元（CAGR 170%），全球SST市场超1000亿元。这不仅是技术升级，更是一次由物理规律驱动的、不可逆的产业变革。</p><hr><h2 id="一、宏观环境-pest" tabindex="-1">一、宏观环境（PEST） <a class="header-anchor" href="#一、宏观环境-pest" aria-label="Permalink to &quot;一、宏观环境（PEST）&quot;">​</a></h2><h3 id="政策-policy" tabindex="-1">政策（Policy） <a class="header-anchor" href="#政策-policy" aria-label="Permalink to &quot;政策（Policy）&quot;">​</a></h3><ul><li><strong>中国</strong>：2026年政府工作报告明确&quot;人工智能+&quot;行动，支持智算中心建设；新版数据中心设计规范将HVDC列为推荐供电架构；&quot;十五五&quot;规划将HVDC纳入算力基础设施关键技术</li><li><strong>欧盟</strong>：修订能效指令，对超过1MW的数据中心强制要求直流供电比例不低于15%</li><li><strong>美国</strong>：IRA法案下ITC税收抵免覆盖数据中心节能改造，北美&quot;自带电源&quot;政策推动燃气轮机+HVDC直供模式落地</li><li><strong>标准进展</strong>：IEC于2025年12月发布400V直流系统安全标准草案，预计2027年正式实施；中国已发布240V/336V直流供电国家标准</li></ul><h3 id="经济-economy" tabindex="-1">经济（Economy） <a class="header-anchor" href="#经济-economy" aria-label="Permalink to &quot;经济（Economy）&quot;">​</a></h3><ul><li>全球数据中心IT负载功率突破75GW（2025年），2030年预计达96GW（SemiAnalysis）</li><li>全球数据中心电源系统市场规模：$21.5B（2025）→ $56.5B（2034），CAGR 16.2%</li><li>AI数据中心的电力成本占OPEX比例从15%升至25%+，能效每提升1%对应数亿美元节约</li><li>电力设备整体处于&quot;超级周期&quot;——&quot;十五五&quot;国家电网投资预计4万亿元，较&quot;十四五&quot;增长40%</li></ul><h3 id="社会-society" tabindex="-1">社会（Society） <a class="header-anchor" href="#社会-society" aria-label="Permalink to &quot;社会（Society）&quot;">​</a></h3><ul><li>HVDC渗透率在新建数据中心中突破18%，2026年预计首超20%临界点</li><li>互联网云服务商（ICP）在HVDC采购中占比达61%，较2023年提升12pp</li><li>金融与制造业数据中心HVDC接受度上升，非互联网行业占比达24%</li><li>全国约40%的标准机架符合绿色改造条件，HVDC改造经济性日益突出</li></ul><h3 id="技术-technology" tabindex="-1">技术（Technology） <a class="header-anchor" href="#技术-technology" aria-label="Permalink to &quot;技术（Technology）&quot;">​</a></h3><ul><li>SiC碳化硅器件在整流模块中采用率跃升至32%，推动系统效率从96%向98.5%+迈进</li><li>2025年全球HVDC相关专利申请量同比增27%，中国申请人占比超54%</li><li>800V HVDC预计2027年进入大规模部署，成为产业链从&quot;试水&quot;到&quot;放量&quot;的分水岭</li></ul><hr><h2 id="二、产业链分析" tabindex="-1">二、产业链分析 <a class="header-anchor" href="#二、产业链分析" aria-label="Permalink to &quot;二、产业链分析&quot;">​</a></h2><h3 id="供电架构演进路线" tabindex="-1">供电架构演进路线 <a class="header-anchor" href="#供电架构演进路线" aria-label="Permalink to &quot;供电架构演进路线&quot;">​</a></h3><p>数据中心供电链路传统由四个层级构成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10kV市电 → 变压器(10kV→380V) → UPS(AC/DC→DC/AC) → 服务器PSU(AC→DC) → 板卡电源(DC→1V)</span></span></code></pre></div><p>HVDC架构精简为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>10kV市电 → SST/整流器(直接10kV→800VDC) → 高压DC/DC → 板卡电源</span></span></code></pre></div><p><strong>UPS vs HVDC核心对比：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>传统UPS</th><th>HVDC</th><th>SST（终态）</th></tr></thead><tbody><tr><td>系统效率</td><td>92-94%</td><td>96-98%</td><td>98%+</td></tr><tr><td>转换级数</td><td>4-5级</td><td>2-3级</td><td>1-2级</td></tr><tr><td>铜用量</td><td>基准</td><td>减少45%</td><td>减少70%+</td></tr><tr><td>占地面积</td><td>基准</td><td>减少40%</td><td>减少80%+</td></tr><tr><td>TCO</td><td>基准</td><td>降低30%</td><td>降低40%+</td></tr><tr><td>适用功率</td><td>≤100kW/rack</td><td>100kW-1MW/rack</td><td>1MW+/rack</td></tr></tbody></table><h3 id="受益链条三层价值分布" tabindex="-1">受益链条三层价值分布 <a class="header-anchor" href="#受益链条三层价值分布" aria-label="Permalink to &quot;受益链条三层价值分布&quot;">​</a></h3><h4 id="第一层-最肥环节-hvdc电源系统" tabindex="-1">第一层（最肥环节）：HVDC电源系统 <a class="header-anchor" href="#第一层-最肥环节-hvdc电源系统" aria-label="Permalink to &quot;第一层（最肥环节）：HVDC电源系统&quot;">​</a></h4><p><strong>价值占比</strong>: 约50-55%产业链利润 <strong>进入壁垒</strong>: 高（国家标准制定、客户验证周期3年+、供应链认证）</p><table tabindex="0"><thead><tr><th>公司</th><th>国内HVDC市占率</th><th>核心优势</th><th>覆盖阶段</th></tr></thead><tbody><tr><td><strong>中恒电气</strong></td><td>31%（第一）</td><td>国家标准制定者，深度绑定阿里/腾讯/三大运营商，巴拿马电源首创者</td><td>240V/336V/800V全系列</td></tr><tr><td><strong>维谛技术/Vertiv</strong></td><td>25%</td><td>全球数据中心基础设施龙头，英伟达800V战略合作伙伴</td><td>800V HVDC产品线（2026H2发布）</td></tr><tr><td><strong>华为数字能源</strong></td><td>22%</td><td>全栈自研，品牌力强</td><td>240V/336V + 预制化电力模块</td></tr><tr><td><strong>科华数据</strong></td><td>12%</td><td>UPS龙头转型，已获国内头部云厂商订单，切入北美CSP</td><td>ZL系列HVDC（240V/336V）</td></tr><tr><td><strong>麦格米特</strong></td><td>—</td><td>进入英伟达AI电源供应链，800V HVDC</td><td>800V sidecar方案</td></tr><tr><td><strong>科士达</strong></td><td>—</td><td>海外营收占比52%，Q2-Q3推出800V HVDC产品</td><td>240V/336V/800V（即将推出）</td></tr><tr><td><strong>阳光电源</strong></td><td>—</td><td>光伏逆变器技术同源，PowerTitan 3.0天然适配HVDC</td><td>SST+HVDC双向布局</td></tr><tr><td><strong>盛弘股份</strong></td><td>—</td><td>电力电子技术积累深厚，多产品布局</td><td>HVDC+SST</td></tr></tbody></table><p><strong>行业格局</strong>: CR3=72%（中恒电气31%+维谛25%+华为22%），寡头垄断格局已成型。</p><h4 id="第二层-变压器-sst" tabindex="-1">第二层：变压器/SST <a class="header-anchor" href="#第二层-变压器-sst" aria-label="Permalink to &quot;第二层：变压器/SST&quot;">​</a></h4><p><strong>价值占比</strong>: 约25-30% <strong>进入壁垒</strong>: 中高（电力设备认证、技术积累）</p><table tabindex="0"><thead><tr><th>环节</th><th>关键公司</th><th>核心逻辑</th></tr></thead><tbody><tr><td>移相变压器（巴拿马核心）</td><td><strong>伊戈尔</strong></td><td>移相变压器龙头，巴拿马电源关键部件</td></tr><tr><td>AIDC变压器</td><td><strong>金盘科技</strong></td><td>国内AIDC变压器领军，订单排到2027年</td></tr><tr><td>SST（固态变压器）</td><td><strong>四方股份</strong>、<strong>中国西电</strong></td><td>SST进度国内领先，产业化陆续推进中</td></tr><tr><td>SST核心零部件（高频变）</td><td><strong>新特电气</strong>、<strong>京泉华</strong>、<strong>可立克</strong></td><td>高频变压器供应商，受益SST放量</td></tr></tbody></table><h4 id="第三层-元器件-配电" tabindex="-1">第三层：元器件/配电 <a class="header-anchor" href="#第三层-元器件-配电" aria-label="Permalink to &quot;第三层：元器件/配电&quot;">​</a></h4><p><strong>价值占比</strong>: 约15-20% <strong>进入壁垒</strong>: 中（需认证和产能）</p><table tabindex="0"><thead><tr><th>环节</th><th>关键公司</th><th>核心逻辑</th></tr></thead><tbody><tr><td>整流模块</td><td><strong>通合科技</strong></td><td>通信电源模块龙头，延展至HVDC</td></tr><tr><td>SiC功率器件</td><td>英飞凌、德州仪器、意法半导体、Navitas</td><td>800V架构下SiC成为必选项</td></tr><tr><td>高压DC/DC转换</td><td>台达电子（核心供应商）、Flex、LiteOn</td><td>壁垒最高、毛利率最厚的环节之一</td></tr><tr><td>高频磁性器件</td><td>京泉华、可立克</td><td>SST和高频电源模块用量大增</td></tr><tr><td>800V直流配电柜</td><td>施耐德、ABB、伊顿、Vertiv</td><td>尚处产品研发期，独立配电柜产品较少</td></tr></tbody></table><h3 id="价值分布结论" tabindex="-1">价值分布结论 <a class="header-anchor" href="#价值分布结论" aria-label="Permalink to &quot;价值分布结论&quot;">​</a></h3><p><strong>最肥环节：HVDC电源系统（中恒电气、维谛、华为）</strong>——标准化程度最低、客户黏性最强、国产替代空间最大、毛利率最高（约35-45%）。其次是变压器/SST环节（毛利率约25-35%），最次是元器件（毛利率15-25%但量最大）。</p><hr><h2 id="三、技术路线对比" tabindex="-1">三、技术路线对比 <a class="header-anchor" href="#三、技术路线对比" aria-label="Permalink to &quot;三、技术路线对比&quot;">​</a></h2><h3 id="四阶段演进路径-semianalysis框架" tabindex="-1">四阶段演进路径（SemiAnalysis框架） <a class="header-anchor" href="#四阶段演进路径-semianalysis框架" aria-label="Permalink to &quot;四阶段演进路径（SemiAnalysis框架）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>时间</th><th>核心特征</th><th>增量设备</th><th>关键标志</th></tr></thead><tbody><tr><td>Phase1</td><td>2026-2027</td><td>白空间改造</td><td>HVDC电源侧柜</td><td>NV Rubin Ultra 2027量产</td></tr><tr><td>Phase2</td><td>2027-2028</td><td>800V原生计算</td><td>BBU+超级电容替代UPS</td><td>Kyber机架规模出货</td></tr><tr><td>Phase3</td><td>2028-2029</td><td>设施级800VDC配电</td><td>800V直流配电体系</td><td>39GW容量目标</td></tr><tr><td>Phase4</td><td>2029+</td><td>SST终态</td><td>固态变压器全面替代工频变</td><td>SST成为AIDC主流方案</td></tr></tbody></table><h3 id="国内外技术路线分化" tabindex="-1">国内外技术路线分化 <a class="header-anchor" href="#国内外技术路线分化" aria-label="Permalink to &quot;国内外技术路线分化&quot;">​</a></h3><p><strong>国内路线</strong>（240/336V HVDC + 巴拿马电源）：</p><ul><li>产业化应用较早（2008年起源于通信基站）</li><li>巴拿马电源（阿里/腾讯主导）将变压器+整流一体化，系统效率97.5%</li><li>巴拿马电源CAPEX相比UPS降低显著，预计在新建AIDC中占主流</li><li>800V产品已在研发，中恒电气最快2026Q4推出</li></ul><p><strong>海外路线</strong>（直接800V + ±400V过渡）：</p><ul><li>NVIDIA主导：800VDC，Kyber机架2027量产，单机架600kW→1MW</li><li>Google/Meta推动：±400VDC过渡方案（2026年末接单，2027Q1量产）</li><li>台达电子有望首家量产独立800VDC电源机柜（2026Q4交付）</li><li>Sidecar方案：功率密度高但量产难度大</li></ul><h3 id="sst-终极方案" tabindex="-1">SST：终极方案 <a class="header-anchor" href="#sst-终极方案" aria-label="Permalink to &quot;SST：终极方案&quot;">​</a></h3><p>固态变压器用SiC/GaN高频开关替代工频变压器，体积缩小80%+，效率98%+，支持双向功率流动和绿电直接接入。国内产业进程全球领先，预计2027H2开始放量，2029-2030成为AIDC柜外电源主流方案。全球SST市场2030年超1000亿元。</p><hr><h2 id="四、竞争格局" tabindex="-1">四、竞争格局 <a class="header-anchor" href="#四、竞争格局" aria-label="Permalink to &quot;四、竞争格局&quot;">​</a></h2><h3 id="全球数据中心hvdc竞争格局" tabindex="-1">全球数据中心HVDC竞争格局 <a class="header-anchor" href="#全球数据中心hvdc竞争格局" aria-label="Permalink to &quot;全球数据中心HVDC竞争格局&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高                          中恒电气(31%) 维谛(25%) 华为(22%)</span></span>
<span class="line"><span>端                    科华数据(12%)  麦格米特  科士达</span></span>
<span class="line"><span>核                  阳光电源  禾望电气  盛弘股份</span></span>
<span class="line"><span>心              台达电子(全球PSU龙头)</span></span>
<span class="line"><span>能            四方股份  中国西电(SST先行者)</span></span>
<span class="line"><span>力           伊戈尔(移相变)  金盘科技(变压器)</span></span></code></pre></div><h3 id="国内竞争特征" tabindex="-1">国内竞争特征 <a class="header-anchor" href="#国内竞争特征" aria-label="Permalink to &quot;国内竞争特征&quot;">​</a></h3><ol><li><strong>CR3=72%</strong>，高度寡头垄断</li><li><strong>中恒电气</strong>是标准制定者+最大份额持有者，深度绑定阿里/腾讯/三大运营商</li><li><strong>华为数字能源</strong>全栈能力最强但聚焦自身生态</li><li><strong>维谛/Vertiv</strong>在外资高端市场保持优势</li><li><strong>宁德时代41亿战略投资中恒电气</strong>——&quot;电池+电力电子&quot;一体化战略，强化竞争力</li></ol><h3 id="海外竞争特征" tabindex="-1">海外竞争特征 <a class="header-anchor" href="#海外竞争特征" aria-label="Permalink to &quot;海外竞争特征&quot;">​</a></h3><ol><li>NVIDIA构建800V生态系统：台达（核心电源）+ Vertiv（基础设施）+ TI/Infineon（功率器件）</li><li>施耐德、ABB、伊顿加速布局SST赛道</li><li>国内企业出海加速：中恒电气新加坡子公司+与SuperX合资+施耐德CEO访问</li></ol><hr><h2 id="五、关键驱动因素与风险" tabindex="-1">五、关键驱动因素与风险 <a class="header-anchor" href="#五、关键驱动因素与风险" aria-label="Permalink to &quot;五、关键驱动因素与风险&quot;">​</a></h2><h3 id="增长驱动" tabindex="-1">增长驱动 <a class="header-anchor" href="#增长驱动" aria-label="Permalink to &quot;增长驱动&quot;">​</a></h3><ol><li><strong>AI算力指数级增长</strong>：全球AI数据中心装机容量从2GW（2023）→21GW（2027），增长10倍</li><li><strong>机架功率密度攀升</strong>：从65kW（2024）→120kW（2026）→1MW+（2028），HVDC是必要条件而非选择</li><li><strong>能效法规趋严</strong>：PUE硬性要求驱动HVDC渗透率提升</li><li><strong>NVIDIA主导标准化</strong>：白皮书明确800V DC路线，全产业链协同推进</li><li><strong>SiC/GaN技术成熟</strong>：功率半导体突破使高电压架构经济可行</li></ol><h3 id="风险因素" tabindex="-1">风险因素 <a class="header-anchor" href="#风险因素" aria-label="Permalink to &quot;风险因素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险</th><th>描述</th><th>影响程度</th><th>时间维度</th></tr></thead><tbody><tr><td><strong>技术落地节奏</strong></td><td>800V安全标准、施工规范尚未统一</td><td>高</td><td>2026-2027</td></tr><tr><td><strong>供应链瓶颈</strong></td><td>高端SiC器件产能受限，国产衬底自给率仅37%</td><td>中高</td><td>2026-2028</td></tr><tr><td><strong>替代技术路线</strong></td><td>±400V分流、48V架构仍有优化空间</td><td>中</td><td>持续</td></tr><tr><td><strong>Capex压力</strong></td><td>全面替换硬件成本高，影响采用率</td><td>中</td><td>短期</td></tr><tr><td><strong>竞争加剧</strong></td><td>光伏逆变器企业跨界进入（阳光电源、德业）</td><td>中</td><td>2027+</td></tr><tr><td><strong>AI资本开支周期</strong></td><td>若AI投资降温，数据中心建设放缓</td><td>中</td><td>宏观</td></tr></tbody></table><hr><h2 id="六、投资结论" tabindex="-1">六、投资结论 <a class="header-anchor" href="#六、投资结论" aria-label="Permalink to &quot;六、投资结论&quot;">​</a></h2><h3 id="核心thesis" tabindex="-1">核心Thesis <a class="header-anchor" href="#核心thesis" aria-label="Permalink to &quot;核心Thesis&quot;">​</a></h3><p><strong>2026年是HVDC产业化元年，2027年是规模出货分水岭。</strong> 从变压器到配电柜的全产业链迎来千亿级替换市场，最肥环节在HVDC电源系统。</p><h3 id="关键假设" tabindex="-1">关键假设 <a class="header-anchor" href="#关键假设" aria-label="Permalink to &quot;关键假设&quot;">​</a></h3><ol><li>NVIDIA Rubin Ultra/Kyber 2027年如期量产</li><li>800V安全标准2027年前完成制定</li><li>SiC/GaN供应链瓶颈在2026-2027年逐步缓解</li><li>AI资本开支2026-2028年保持30%+增速</li></ol><h3 id="受益优先级" tabindex="-1">受益优先级 <a class="header-anchor" href="#受益优先级" aria-label="Permalink to &quot;受益优先级&quot;">​</a></h3><p><strong>① HVDC电源系统</strong>（最肥）→ <strong>② SST/变压器</strong> → <strong>③ 元器件/配电柜</strong></p><h3 id="多空情景" tabindex="-1">多空情景 <a class="header-anchor" href="#多空情景" aria-label="Permalink to &quot;多空情景&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情景</th><th>概率</th><th>条件</th><th>核心受益</th></tr></thead><tbody><tr><td>乐观</td><td>35%</td><td>800V快速标准化，NV Rubin放量超预期</td><td>HVDC电源+SST双主线</td></tr><tr><td>基准</td><td>50%</td><td>按四阶段稳步推进</td><td>HVDC电源先行，SST后发</td></tr><tr><td>悲观</td><td>15%</td><td>800V标准延迟，NV产品跳票</td><td>240V/336V HVDC延续增长</td></tr></tbody></table><h3 id="需要进一步验证的问题" tabindex="-1">需要进一步验证的问题 <a class="header-anchor" href="#需要进一步验证的问题" aria-label="Permalink to &quot;需要进一步验证的问题&quot;">​</a></h3><ol><li>800V安全标准实际落地时间表</li><li>中恒电气800V产品推出节奏及客户验证进度</li><li>SST的工程化成熟度与实际成本曲线</li><li>北美&quot;自带电源&quot;模式对中国供应链的实际拉动规模</li></ol><hr><blockquote><p><strong>免责声明</strong>: 本报告仅为行业研究分析，不构成任何投资建议。数据来源包括Precedence Research、SemiAnalysis、QYResearch、TrendForce、东吴证券、华鑫证券、招商证券等公开研究报告及新闻媒体，数据截止2026年6月。市场有风险，投资需谨慎。</p></blockquote>`,76)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
